def is_plain_name(name: str) -> bool:
    """True when name is one file name with no path parts, so it cannot leave its directory."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../secret") == False
    ex is_plain_name("sub/a.txt") == False
    ex is_plain_name("") == False
    if name == "" or name == "." or name == "..":
        return False
    if "/" in name or "\\" in name:
        return False
    return True

def first_readable(names: list[str]) -> str uses fs:
    """Text of the first name in names that can be read from the notes directory, or "" when none can.
    Names that are not plain file names are never opened, and a missing or unreadable file is skipped."""
    post out == "" or names.len() > 0
    with fs = fs.sub("notes"):
        for name in names:
            if not is_plain_name(name):
                continue
            text = fs.read(name) else ""
            if text != "":
                return text
    return ""
